(function(){
  'use strict';
  if(window._tpLoaderInitialized) return;
  window._tpLoaderInitialized = true;

  var config = window._tpLoaderConfig || { timeout: 3500 };
  var executed = false;
  var timer = null;
  var events = ['keydown', 'mousemove', 'touchstart', 'scroll', 'click', 'wheel'];

  // Failed-script reporting (consumed by the RUM beacon in v1.4).
  window._tpFailedScripts = window._tpFailedScripts || [];

  function triggerLoad() {
    if (executed) return;
    executed = true;

    events.forEach(function(e) {
      window.removeEventListener(e, triggerLoad, { passive: true });
    });
    if (timer) clearTimeout(timer);

    var scripts = Array.prototype.slice.call(document.querySelectorAll('script[type="text/turbopress"]'));
    scripts.sort(function(a, b) {
      var orderA = parseInt(a.getAttribute('data-tp-order') || '9999', 10);
      var orderB = parseInt(b.getAttribute('data-tp-order') || '9999', 10);
      return orderA - orderB;
    });

    executeScriptChain(scripts, 0, function() {
      // Drain jQuery stub queue
      if (window._tpJQueue && window._tpJQueue.length > 0 && typeof window.jQuery === 'function') {
        while (window._tpJQueue.length > 0) {
          var fn = window._tpJQueue.shift();
          try {
            if (typeof fn === 'function') fn(window.jQuery);
          } catch(err) {
            console.error('[Turbopress jQuery Callback Error]', err);
          }
        }
      }
      // Dispatch custom event
      window.dispatchEvent(new CustomEvent('turbopress:scripts_loaded'));
    });
  }

  function executeScriptChain(scripts, index, callback) {
    if (index >= scripts.length) {
      if (callback) callback();
      return;
    }

    var original = scripts[index];
    var replacement = document.createElement('script');

    // Copy attributes
    for (var i = 0; i < original.attributes.length; i++) {
      var attr = original.attributes[i];
      if (attr.name !== 'type' && attr.name !== 'data-tp-src' && attr.name !== 'data-tp-order') {
        replacement.setAttribute(attr.name, attr.value);
      }
    }

    var tpSrc = original.getAttribute('data-tp-src');
    if (tpSrc) {
      replacement.src = tpSrc;
      replacement.onerror = function() {
        // Per-script isolation: a failed fetch never stalls the chain.
        try { window._tpFailedScripts.push({ src: tpSrc, reason: 'network' }); } catch (e) {}
        executeScriptChain(scripts, index + 1, callback);
      };
      replacement.onload = function() {
        executeScriptChain(scripts, index + 1, callback);
      };
      original.parentNode.replaceChild(replacement, original);
    } else {
      replacement.text = original.text || original.textContent;
      original.parentNode.replaceChild(replacement, original);
      // Runtime exceptions in one inline script must not abort the rest.
      try {
        // Nothing to await — inline scripts execute synchronously on insert.
      } catch (err) {
        try { window._tpFailedScripts.push({ reason: 'inline', index: index }); } catch (e) {}
      }
      executeScriptChain(scripts, index + 1, callback);
    }
  }

  // Register user interaction triggers
  events.forEach(function(e) {
    window.addEventListener(e, triggerLoad, { passive: true, once: true });
  });

  // Guaranteed execution fallback: the safety timer counts from
  // DOMContentLoaded (not from this deferred loader's execution), so pages
  // can never end up with permanently withheld scripts.
  function armFallbackTimer() {
    if (config.timeout > 0 && !executed && timer === null) {
      timer = setTimeout(triggerLoad, config.timeout);
    }
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', armFallbackTimer, { once: true });
  } else {
    armFallbackTimer();
  }
})();
